export default JSON.parse(
  "{\n  \"workId\": \"mo-zi\",\n  \"chapter\": {\n    \"id\": \"mo-zi_ch-27\",\n    \"workId\": \"mo-zi\",\n    \"order\": 27,\n    \"title\": \"天志中\",\n    \"difficulty\": 5,\n    \"estimatedMinutes\": 11,\n    \"passageIds\": [\n      \"mo-zi_ch-27_p-1\",\n      \"mo-zi_ch-27_p-2\",\n      \"mo-zi_ch-27_p-3\",\n      \"mo-zi_ch-27_p-4\",\n      \"mo-zi_ch-27_p-5\",\n      \"mo-zi_ch-27_p-6\",\n      \"mo-zi_ch-27_p-7\",\n      \"mo-zi_ch-27_p-8\",\n      \"mo-zi_ch-27_p-9\"\n    ],\n    \"tags\": [\n      \"墨家\",\n      \"墨子\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"mo-zi_ch-27_p-1\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"order\": 1,\n      \"canonicalText\": \"子墨子言曰：「今天下之君子之慾為仁義者，則不可不察義之所從出。既曰不可以不察義之所從出，然則義何從出？」子墨子曰：「義不從愚且賤者出，必自貴且知者出。何以知義之不從愚且賤者出，而必自貴且知者出也？曰：義者，善政也。何以知義之為善政也？曰：天下有義則治，無義則亂，是以知義之為善政也。夫愚且賤者，不得為政乎貴且知者，貴且知者然後得為政乎愚且賤者，此吾所以知義之不從愚且賤者出，而必自貴且知者出也。然則孰為貴？孰為知？曰：天為貴，天為知而已矣。然則義果自天出矣。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-27_p-1_s-1\",\n        \"mo-zi_ch-27_p-1_s-2\",\n        \"mo-zi_ch-27_p-1_s-3\",\n        \"mo-zi_ch-27_p-1_s-4\",\n        \"mo-zi_ch-27_p-1_s-5\",\n        \"mo-zi_ch-27_p-1_s-6\",\n        \"mo-zi_ch-27_p-1_s-7\",\n        \"mo-zi_ch-27_p-1_s-8\",\n        \"mo-zi_ch-27_p-1_s-9\",\n        \"mo-zi_ch-27_p-1_s-10\",\n        \"mo-zi_ch-27_p-1_s-11\",\n        \"mo-zi_ch-27_p-1_s-12\",\n        \"mo-zi_ch-27_p-1_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"墨子說道：「當今天下的士人君子若真心想要實踐仁義，就不可不詳加考察『義』究竟是從何處產生的。既然說不可不察明義的來源，那麼義究竟是從何而來的呢？義絕不可能從愚昧且地位卑賤的人那裡產生，而必定是從尊貴且智慧超絕的存在那裡產生。憑何得知義是從尊貴且具大智慧者那裡產生的呢？因為義本是匡正救偏的善道；唯有智慧高遠者方能制定公正法度，愚頑下賤者往往行私枉法而難以立綱紀。因此，義絕不由愚賤之人創造，必定來源於天下最尊貴且最有智慧的主宰——那就是至高無上的天帝。」\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志中〉。墨子學派以兼愛天下為宗，開篇「子墨子言曰：「今天下之君子之慾為仁義者，則不可不察義之所從出」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「言」、「今」、「天」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「子墨子言曰今天下之君子之慾為仁義者則不可不察義之」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「既曰不可以不察義之所從出，然則義何從出」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"order\": 2,\n      \"canonicalText\": \"今天下之人曰：「當若天子之貴於諸侯，諸侯之貴於大夫，傐明知之。然吾未知天之貴且知於天子也。」子墨子曰：「吾所以知天之貴且知於天子者有矣。曰：天子為善，天能賞之；天子為暴，天能罰之；天子有疾病禍祟，必齋戒沐浴，潔為酒醴粢盛，以祭祀天鬼，則天能除去之，然吾未知天之祈福於天子也。此吾所以知天之貴且知於天子者。不止此而已矣，又以先王之書馴天明不解之道也知之。曰：『明哲維天，臨君下土。』則此語天之貴且知於天子。不知亦有貴知夫天者乎？曰：天為貴，天為知而已矣。然則義果自天出矣。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-27_p-2_s-1\",\n        \"mo-zi_ch-27_p-2_s-2\",\n        \"mo-zi_ch-27_p-2_s-3\",\n        \"mo-zi_ch-27_p-2_s-4\",\n        \"mo-zi_ch-27_p-2_s-5\",\n        \"mo-zi_ch-27_p-2_s-6\",\n        \"mo-zi_ch-27_p-2_s-7\",\n        \"mo-zi_ch-27_p-2_s-8\",\n        \"mo-zi_ch-27_p-2_s-9\",\n        \"mo-zi_ch-27_p-2_s-10\",\n        \"mo-zi_ch-27_p-2_s-11\",\n        \"mo-zi_ch-27_p-2_s-12\",\n        \"mo-zi_ch-27_p-2_s-13\",\n        \"mo-zi_ch-27_p-2_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今天下的人說道：當若天子的貴於諸侯，諸侯的貴於大夫，傐明知的。然吾未知天的貴且知於天子啊。墨子先生親自教導說道：吾所以知天的貴且知於天子的人有矣。說道：天子為善，天能賞的；天子為暴，天能罰的；天子有疾病禍祟，必齋戒沐浴，潔為酒醴粢盛，以祭祀天鬼，則天能除去的，然吾未知天的祈福於天子啊。此吾所以知天的貴且知於天子的人。不止此而且已矣，又以先王的書馴天明不解的道啊知的。說道：明哲維天，臨君下土。則此語天的貴且知於天子。不知亦有貴知夫天的人乎？說道：天為貴，天為知而且已矣。然則義果自天出矣。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志中〉。墨子學派以兼愛天下為宗，開篇「今天下之人曰：「當若天子之貴於諸侯，諸侯之貴於大夫，傐明知之」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「今」、「天」、「下」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「今天下之人曰當若天子之貴於諸侯諸侯之貴於大夫傐明」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「然吾未知天之貴且知於天子也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"order\": 3,\n      \"canonicalText\": \"是故子墨子曰：「今天下之君子，中實將欲遵道利民，本察仁義之本，天之意不可不慎也。」既以天之意以為不可不慎已，然則天之將何欲何憎？子墨子曰：「天之意不欲大國之攻小國也，大家之亂小家也，強之暴寡，詐之謀愚，貴之傲賤，此天之所不欲也。不止此而已，欲人之有力相營，有道相教，有財相分也。又欲上之強聽治也，下之強從事也。上強聽治，則國家治矣，下強從事則財用足矣。若國家治財用足，則內有以潔為酒醴粢盛，以祭祀天鬼；外有以為環璧珠玉，以聘撓四鄰。諸侯之冤不興矣，邊境兵甲不作矣。內有以食飢息勞，持養其萬民，則君臣上下惠忠，父子弟兄慈孝。故唯毋明乎順天之意，奉而光施之天下，則刑政治，萬民和，國家富，財用足，百姓皆得煖衣飽食，便寧無憂。」是故子墨子曰：「今天下之君子，中實將欲遵道利民，本察仁義之本，天之意不可不慎也！」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-27_p-3_s-1\",\n        \"mo-zi_ch-27_p-3_s-2\",\n        \"mo-zi_ch-27_p-3_s-3\",\n        \"mo-zi_ch-27_p-3_s-4\",\n        \"mo-zi_ch-27_p-3_s-5\",\n        \"mo-zi_ch-27_p-3_s-6\",\n        \"mo-zi_ch-27_p-3_s-7\",\n        \"mo-zi_ch-27_p-3_s-8\",\n        \"mo-zi_ch-27_p-3_s-9\",\n        \"mo-zi_ch-27_p-3_s-10\",\n        \"mo-zi_ch-27_p-3_s-11\",\n        \"mo-zi_ch-27_p-3_s-12\",\n        \"mo-zi_ch-27_p-3_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"因此墨子說：「當今天下的士人君子，如果內心真想遵循正道、利益民眾，探求仁義的根本源頭，那麼對於上天的意願便不可不謹慎敬畏了。」既然認定上天的意願不可不謹慎遵從，那麼上天究竟期盼什麼、厭惡什麼呢？墨子說：「上天的意願，不希望大國攻打小國，不希望強大家族騷擾弱小家族，不希望強者欺凌弱小，不希望狡詐者欺瞞愚鈍者，不希望尊貴者傲視卑賤者，這一切都是上天所厭惡不欲見的。不僅如此，上天希望人與人之間能以力相助、同心協力，掌握道術者能相互施教啟迪，擁有財富者能相互周濟分潤。上天又希望在上位者能勤勉聽察治理政事，在下位者能竭力從事耕織勞作。上位者勤於聽政，國家便綱紀清明秩序井然；下位者奮發勞作，社會的財富物資便充裕富足。如果國家大治且物產充足，那麼對內便有充足資源備辦清潔的酒醴黍稷來祭祀天帝與鬼神；對外便有珍寶璧玉去聯絡通好四鄰諸侯。諸侯之間不起怨隙紛爭，邊境要塞便無戰事烽煙。對內有糧食救濟飢民、撫慰勞苦，休養生息萬民，君臣上下便能各盡惠愛與忠誠，父子兄弟便能各行慈愛與孝悌。所以只要體明順應天意，將天志彰顯推行於天下，那麼刑法政令自能清明，萬民和睦無怨，國家富庶豐饒，財用充盈充足，百姓皆得溫飽安康，悠然寧靜而無凍餒憂慮。」因此墨子說：「當今天下的士人君子，若內心真心想要遵循大道、造福萬民，本求考察仁義的本源，上天的意旨是不可不謹慎遵奉的！」\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志中〉。墨子學派以兼愛天下為宗，開篇「是故子墨子曰：「今天下之君子，中實將欲遵道利民，本察仁義之本，天之意不可不慎也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「是」、「今」、「天」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「是故子墨子曰今天下之君子中實將欲遵道利民本察仁義」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「」既以天之意以為不可不慎已，然則天之將何欲何憎」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"order\": 4,\n      \"canonicalText\": \"且夫天子之有天下也，闢之無以異乎國君諸侯之有四境之內也。今國君諸侯之有四境之內也，夫豈欲其臣國萬民之相為不利哉？今若處大國則攻小國，處大家則亂小家，欲以此求賞譽，終不可得，誅罰必至矣。夫天之有天下也，將無已異此。今若處大國則攻小國，處大都則伐小都，欲以此求福祿於天，福祿終不得，而禍祟必至矣。然有所不為天之所欲，而為天之所不欲，則夫天亦且不為人之所欲，而為人之所不欲矣。人之所不欲者何也？曰病疾禍祟也。若已不為天之所欲，而為天之所不欲，是率天下之萬民以從事乎禍祟之中也。故古者聖王明知天鬼之所福，而闢天鬼之所憎，以求興天下之利，而除天下之害。是以天之為寒熱也節，四時調，陰陽雨露也時，五穀孰，六畜遂，疾災戾疫凶饑則不至。」是故子墨子曰：「今天下之君子，中實將欲遵道利民，本察仁義之本，天意不可不慎也！」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-27_p-4_s-1\",\n        \"mo-zi_ch-27_p-4_s-2\",\n        \"mo-zi_ch-27_p-4_s-3\",\n        \"mo-zi_ch-27_p-4_s-4\",\n        \"mo-zi_ch-27_p-4_s-5\",\n        \"mo-zi_ch-27_p-4_s-6\",\n        \"mo-zi_ch-27_p-4_s-7\",\n        \"mo-zi_ch-27_p-4_s-8\",\n        \"mo-zi_ch-27_p-4_s-9\",\n        \"mo-zi_ch-27_p-4_s-10\",\n        \"mo-zi_ch-27_p-4_s-11\",\n        \"mo-zi_ch-27_p-4_s-12\",\n        \"mo-zi_ch-27_p-4_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"況且天子擁有天下，打個比方，這與國君諸侯擁有自己四方疆界之內的領土毫無差異。如今各國君主諸侯擁有四境之內的土地，難道會希望自己治下的臣民各邑彼此傷害、自相殘殺嗎？如今若有人依仗本國強大就攻打鄰近弱小城邑，依仗家族強盛就擾亂弱小族姓，企圖以此向國君求取賞賜與稱譽，最終是絕對無法獲得的，反而必會招致嚴酷的誅戮懲罰。天帝擁抱普天之下，其心意與此完全沒有分別。如今各國若依仗地廣兵強就攻伐弱小鄰國，依託大城重鎮就破滅弱小邑落，企圖以此向天帝乞求福祿恩澤，福祉是終究得不到的，反而天降的災禍禍祟必會降臨其身。如果有人悖逆上天的期許，偏偏去做上天所厭惡的事情，那麼上天也必定不會賜給人們所渴望的福祉，而只會降下人們所深惡痛絕的災殃。人們所厭惡的是什麼呢？就是疫癘疾病與凶喪禍祟。如果自己不去做上天所願見的兼愛善行，專做上天所痛恨的暴虐之事，這就是率領天下萬民一同沉淪於災禍禍害之中。因此古代聖王明瞭天帝鬼神所要賜福的善端，極力避開天帝鬼神所憎惡的惡行，以此謀求興起天下的重大利益，徹底除滅天下的公害。正因如此，上天所賜的寒暑氣候便調適中節，四季運行和順，陰陽調和而雨露及時降臨，五穀豐登成熟，六畜繁育健旺，災疾疫癘與凶荒飢饉便全然不會降臨。」因此墨子告誡說：「當今天下的士人君子，內心真想尊崇大道利濟群生，探究仁義的本質，對天意就絕不可不慎思奉行！」\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志中〉。墨子學派以兼愛天下為宗，開篇「且夫天子之有天下也，闢之無以異乎國君諸侯之有四境之內也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「且」、「天」、「有」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「且夫天子之有天下也闢之無以異乎國君諸侯之有四境之」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「今國君諸侯之有四境之內也，夫豈欲其臣國萬民之相為不利哉」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-5\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"order\": 5,\n      \"canonicalText\": \"且夫天下蓋有不仁不祥者，曰當若子之不事父，弟之不事兄，臣之不事君也。故天下之君子，與謂之不祥者。今夫天兼天下而愛之，撽遂萬物以利之，若豪之末，非天之所為也，而民得而利之，則可謂否矣。然獨無報夫天，而不知其為不仁不祥也。此吾所謂君子明細而不明大也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-27_p-5_s-1\",\n        \"mo-zi_ch-27_p-5_s-2\",\n        \"mo-zi_ch-27_p-5_s-3\",\n        \"mo-zi_ch-27_p-5_s-4\",\n        \"mo-zi_ch-27_p-5_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"再的人況且天下蓋有不仁不祥的人，說道：當若子的不事父，弟的不事兄，臣的不事君啊。所以天下的君子，與謂的不祥的人。如今社會世俗的上的天兼天下而且愛的，撽遂萬物以利的，若豪的末，絕不是天的所為啊，而且民得而且利的，則可謂否矣。然獨無報夫天，而且不知他的為不仁不祥啊。此吾所謂君子明細而且不明大啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志中〉。墨子學派以兼愛天下為宗，開篇「且夫天下蓋有不仁不祥者，曰當若子之不事父，弟之不事兄，臣之不事君也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「且」、「天」、「下」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「且夫天下蓋有不仁不祥者曰當若子之不事父弟之不事兄」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「故天下之君子，與謂之不祥者」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-6\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"order\": 6,\n      \"canonicalText\": \"且吾所以知天之愛民之厚者有矣，曰以磨為日月星辰，以昭道之；制為四時春秋冬夏，以紀綱之；雷降雪霜雨露，以長遂五穀麻絲，使民得而財利之；列為山川谿谷，播賦百事，以臨司民之善否；為王公侯伯，使之賞賢而罰暴；賊金木鳥獸，從事乎五穀麻絲，以為民衣食之財。自古及今，未嘗不有此也。今有人於此，驩若愛其子，竭力單務以利之，其子長，而無報子求父，故天下之君子與謂之不仁不祥。今夫天兼天下而愛之，撽遂萬物以利之，若豪之末，非天之所為，而民得而利之，則可謂否矣，然獨無報夫天，而不知其為不仁不祥也。此吾所謂君子明細而不明大也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-27_p-6_s-1\",\n        \"mo-zi_ch-27_p-6_s-2\",\n        \"mo-zi_ch-27_p-6_s-3\",\n        \"mo-zi_ch-27_p-6_s-4\",\n        \"mo-zi_ch-27_p-6_s-5\",\n        \"mo-zi_ch-27_p-6_s-6\",\n        \"mo-zi_ch-27_p-6_s-7\",\n        \"mo-zi_ch-27_p-6_s-8\",\n        \"mo-zi_ch-27_p-6_s-9\",\n        \"mo-zi_ch-27_p-6_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"且吾所以知天的愛民的厚的人有矣，說道：以磨為日月星辰，以昭道的；制為四時春秋冬夏，以紀綱的；雷降雪霜雨露，以長遂五穀麻絲，使民得而且財利的；列為山川谿谷，播賦百事，以臨司民的善否；為王公侯伯，使的賞賢而且罰暴；賊金木鳥獸，從事乎五穀麻絲，以為民衣食的財。自古及今，未嘗不有此啊。今有人於此，驩若愛他的子，竭力單務以利的，他的子長，而且無報子求父，所以天下的君子與謂的不仁不祥。如今社會世俗的上的天兼天下而且愛的，撽遂萬物以利的，若豪的末，絕不是天的所為，而且民得而且利的，則可謂否矣，然獨無報夫天，而且不知他的為不仁不祥啊。此吾所謂君子明細而且不明大啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志中〉。墨子學派以兼愛天下為宗，開篇「且吾所以知天之愛民之厚者有矣，曰以磨為日月星辰，以昭道之」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「且」、「吾」、「知」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「且吾所以知天之愛民之厚者有矣曰以磨為日月星辰以昭」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「制為四時春秋冬夏，以紀綱之」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-7\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"order\": 7,\n      \"canonicalText\": \"且吾所以知天愛民之厚者，不止此而足矣。曰殺不辜者，天予不祥。不辜者誰也？曰人也。予之不祥者誰也？曰天也。若天不愛民之厚，夫胡說人殺不辜，而天予之不祥哉？此吾之所以知天之愛民之厚也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-27_p-7_s-1\",\n        \"mo-zi_ch-27_p-7_s-2\",\n        \"mo-zi_ch-27_p-7_s-3\",\n        \"mo-zi_ch-27_p-7_s-4\",\n        \"mo-zi_ch-27_p-7_s-5\",\n        \"mo-zi_ch-27_p-7_s-6\",\n        \"mo-zi_ch-27_p-7_s-7\",\n        \"mo-zi_ch-27_p-7_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"且吾所以知天愛民的厚的人，不止此而且足矣。說道：殺不辜的人，天予不祥。不辜的人誰啊？說道：人啊。予的不祥的人誰啊？說道：天啊。若天不愛民的厚，夫胡推理說理人殺不辜，而且天予的不祥哉？此吾的所以知天的愛民的厚啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志中〉。墨子學派以兼愛天下為宗，開篇「且吾所以知天愛民之厚者，不止此而足矣」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「且」、「吾」、「知」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「且吾所以知天愛民之厚者不止此而足矣曰殺不辜者天予」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「曰殺不辜者，天予不祥」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"order\": 8,\n      \"canonicalText\": \"且吾所以知天之愛民之厚者，不止此而已矣。曰愛人利人，順天之意，得天之賞者有之；憎人賊人，反天之意，得天之罰者亦有矣。夫愛人利人，順天之意，得天之賞者誰也？曰若昔三代聖王，堯舜禹湯文武者是也。堯舜禹湯文武焉所從事？曰從事兼，不從事別。兼者，處大國不攻小國，處大家不亂小家，強不劫弱，眾不暴寡，詐不謀愚，貴不傲賤。觀其事，上利乎天，中利乎鬼，下利乎人，三利無所不利，是謂天德。聚斂天下之美名而加之焉，曰：此仁也，義也，愛人利人，順天之意，得天之賞者也。不止此而已，書於竹帛，鏤之金石，琢之槃盂，傳遺後世子孫。曰將何以為？將以識夫愛人利人，順天之意，得天之賞者也。皇矣道之曰：『帝謂文王，予懷明德，不大聲以色，不長夏以革，不識不知，順帝之則。』帝善其順法則也，故舉殷以賞之，使貴為天子，富有天下，名譽至今不息。故夫愛人利人，順天之意，得天之賞者，既可得留而已。夫憎人賊人，反天之意，得天之罰者誰也？曰若昔者三代暴王桀紂幽厲者是也。桀紂幽厲焉所從事？曰從事別，不從事兼。別者，處大國則攻小國，處大家則亂小家，強劫弱，眾暴寡，詐謀愚，貴傲賤。觀其事，上不利乎天，中不利乎鬼，下不利乎人，三不利無所利，是謂天賊。聚斂天下之醜名而加之焉，曰此非仁也，非義也。憎人賊人，反天之意，得天之罰者也。不止此而已，又書其事於竹帛，鏤之金石，琢之槃盂，傳遺後世子孫。曰將何以為？將以識夫憎人賊人，反天之意，得天之罰者也。大誓之道之曰：『紂越厥夷居，不肯事上帝，棄厥先神祇不祀，乃曰吾有命，毋廖𠏿務天下。天亦縱棄紂而不葆。』察天以縱棄紂而不葆者，反天之意也。故夫憎人賊人，反天之意，得天之罰者，既可得而知也。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-27_p-8_s-1\",\n        \"mo-zi_ch-27_p-8_s-2\",\n        \"mo-zi_ch-27_p-8_s-3\",\n        \"mo-zi_ch-27_p-8_s-4\",\n        \"mo-zi_ch-27_p-8_s-5\",\n        \"mo-zi_ch-27_p-8_s-6\",\n        \"mo-zi_ch-27_p-8_s-7\",\n        \"mo-zi_ch-27_p-8_s-8\",\n        \"mo-zi_ch-27_p-8_s-9\",\n        \"mo-zi_ch-27_p-8_s-10\",\n        \"mo-zi_ch-27_p-8_s-11\",\n        \"mo-zi_ch-27_p-8_s-12\",\n        \"mo-zi_ch-27_p-8_s-13\",\n        \"mo-zi_ch-27_p-8_s-14\",\n        \"mo-zi_ch-27_p-8_s-15\",\n        \"mo-zi_ch-27_p-8_s-16\",\n        \"mo-zi_ch-27_p-8_s-17\",\n        \"mo-zi_ch-27_p-8_s-18\",\n        \"mo-zi_ch-27_p-8_s-19\",\n        \"mo-zi_ch-27_p-8_s-20\",\n        \"mo-zi_ch-27_p-8_s-21\",\n        \"mo-zi_ch-27_p-8_s-22\",\n        \"mo-zi_ch-27_p-8_s-23\",\n        \"mo-zi_ch-27_p-8_s-24\",\n        \"mo-zi_ch-27_p-8_s-25\",\n        \"mo-zi_ch-27_p-8_s-26\",\n        \"mo-zi_ch-27_p-8_s-27\",\n        \"mo-zi_ch-27_p-8_s-28\",\n        \"mo-zi_ch-27_p-8_s-29\",\n        \"mo-zi_ch-27_p-8_s-30\",\n        \"mo-zi_ch-27_p-8_s-31\",\n        \"mo-zi_ch-27_p-8_s-32\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"況且我之所以知道上天愛護民眾之深厚，還遠遠不止於上述這些道理。凡是愛護他人、利益他人，順應上天旨意的人，獲得上天賞賜的事例歷歷在目；而憎恨他人、殘害他人，違背上天旨意的人，遭受上天懲罰的事例也切實存在。那麼愛護他人、利益他人，順應天意而榮獲天賞的人究竟是誰呢？就是昔日三代的聖王堯、舜、禹、商湯、周文王與周武王。堯、舜、禹、湯、文、武平日奉行的是什麼呢？他們奉行的是兼愛之道，而不奉行自私劃界的偏愛。所謂兼愛，就是身處大國而不攻打小國，身處豪門世家而不騷擾小家寡室，身強力壯而不劫掠弱小，人多勢眾而不凌辱寡弱，狡黠巧詐而不欺瞞愚鈍，地位尊貴而不傲慢對待卑賤。審視他們的作為，對上符合天帝的福祉，居中符合鬼神的祭享，對下切合黎民百姓的安康，三者皆受其利而無所損害，這就稱作體現了上天的大德。於是天下人便把一切美好的名號凝聚加諸在他們身上，稱讚說：這就是仁愛，這就是正義，這是愛民利民、順應天意、榮獲天賞的至聖明君！不僅如此，後人還將他們的功業德行書寫在竹簡絲帛上，銘刻在金石鐘鼎上，雕琢在祭祀的盤盂器皿上，世代流傳遺贈給後世子孫。這樣做是為了什麼呢？正是為了讓萬世萬代都能永遠記住這些愛民利民、順應天意並榮獲天帝厚賞的楷模。《詩經·大雅·皇矣》稱頌說：『天帝對文王說：我懷念你純明的至德，不因聲色動怒而厲色待人，不長施嚴威以革罰天下，不憑己意妄作聰明私智，純然順應上帝的準則法則。』天帝嘉許文王能順應天道的準則法度，所以將殷商天下賜予文王之子作為報償，使周朝天子位尊天下、富擁萬邦，其美名榮譽流傳至今延綿不息。因此愛護人民、利益人民、順應天意而榮獲天賞的道理，已是昭然若揭而足可為法了。那麼憎恨人民、殘害人民、違背天意而遭受天罰的人是誰呢？那就是昔日三代的暴君夏桀、商紂、周幽王與周厲王。夏桀、商紂、幽王、厲王平日奉行的是什麼呢？他們奉行的是自私劃界的偏狹，而不奉行兼愛。所謂偏私劃界，就是身處大國便攻打小國，身處豪門便侵擾小家，恃強劫弱，以眾暴寡，狡詐欺愚，居貴傲賤。審視他們的作為，對上觸怒天帝，居中得罪鬼神，對下殘害生靈，三者皆無利益而處處禍國，這就叫做天下的罪賊。於是天下人便把一切醜惡的污名集中加諸在他們身上，批判說：這完全是不仁，完全是不義！這是憎民賊民、違抗天意、招致天罰的暴虐之徒！不僅如此，後人還將他們的暴行遺臭書寫在竹帛之上，鏤刻在金石銘文上，琢磨在鼎彝盤盂上，傳留警惕後世子孫。這樣做又是為了什麼呢？正是為了讓後人永遠鑑戒那些殘民賊物、悖逆天意而遭受天誅的逆賊。《尚書·泰誓》揭露商紂罪行說：『商紂踰越常理夷滅善俗，不肯虔敬事奉上帝，拋棄先祖神靈而不加祭祀，反而狂妄自誇說：我有天命在身，何須為天下瑣事憂心盡瘁？於是上天也決然拋棄商紂而不再庇佑庇護他。』考察上天之所以廢棄商紂而不加保佑的緣由，正是因為他徹底悖逆了天意。因此憎民害人、悖逆天理而必受天誅之罰，其道理同樣是明白昭著、確鑿無疑的。」\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志中〉。墨子學派以兼愛天下為宗，開篇「且吾所以知天之愛民之厚者，不止此而已矣」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「且」、「吾」、「知」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「且吾所以知天之愛民之厚者不止此而已矣曰愛人利人順」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「曰愛人利人，順天之意，得天之賞者有之」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"order\": 9,\n      \"canonicalText\": \"是故子墨子之有天之，闢之無以異乎輪人之有規，匠人之有矩也。今夫輪人操其規，將以量度天下之圜與不圜也，曰：中吾規者謂之圜，不中吾規者謂之不圜。是以圜與不圜，皆可得而知也。此其故何？則圜法明也。匠人亦操其矩，將以量度天下之方與不方也。曰：中吾矩者謂之方，不中吾矩者謂之不方。是以方與不方，皆可得而知之。此其故何？則方法明也。故子墨子之有天之意也，上將以度天下之王公大人之為刑政也，下將以量天下之萬民為文學出言談也。觀其行，順天之意，謂之善意行，反天之意，謂之不善意行；觀其言談，順天之意，謂之善言談，反天之意，謂之不善言談；觀其刑政，順天之意，謂之善刑政，反天之意，謂之不善刑政。故置此以為法，立此以為儀，將以量度天下之王公大人卿大夫之仁與不仁，譬之猶分黑白也。是故子墨子曰：「今天下之王公大人士君子，中實將欲遵道利民，本察仁義之本，天之意不可不順也。順天之意者，義之法也。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-27_p-9_s-1\",\n        \"mo-zi_ch-27_p-9_s-2\",\n        \"mo-zi_ch-27_p-9_s-3\",\n        \"mo-zi_ch-27_p-9_s-4\",\n        \"mo-zi_ch-27_p-9_s-5\",\n        \"mo-zi_ch-27_p-9_s-6\",\n        \"mo-zi_ch-27_p-9_s-7\",\n        \"mo-zi_ch-27_p-9_s-8\",\n        \"mo-zi_ch-27_p-9_s-9\",\n        \"mo-zi_ch-27_p-9_s-10\",\n        \"mo-zi_ch-27_p-9_s-11\",\n        \"mo-zi_ch-27_p-9_s-12\",\n        \"mo-zi_ch-27_p-9_s-13\",\n        \"mo-zi_ch-27_p-9_s-14\",\n        \"mo-zi_ch-27_p-9_s-15\",\n        \"mo-zi_ch-27_p-9_s-16\",\n        \"mo-zi_ch-27_p-9_s-17\",\n        \"mo-zi_ch-27_p-9_s-18\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"因此，墨子提出以天意作為行為標準，打個比方，這與製作車輪的工匠手持圓規、木工匠人手持曲尺毫無二致。如今車匠手持圓規，用來量度普天下的物體究竟是圓還是不圓，宣布說：合乎我的圓規標準的就叫做圓，不合乎我的圓規標準的就叫做不圓。因此天下之物圓與不圓，全都可以清清楚楚地判定。這其中的緣故何在呢？就是因為測量圓形的標準法度明確昭彰。木匠也手持曲尺，用來度量天下的形體究竟是方還是不方，宣布說：合乎我的曲尺標準的就叫做方，不合乎我的曲尺標準的就叫做不方。因此天下的事物方與不方，也全都能夠準確判斷。這其中的緣故何在呢？就是因為測量方形的標準法度明確昭彰。所以墨子確立天之意旨作為最高標準，對上用來衡量天下王公大人的刑罰政令是否得宜，對下用來評判天下萬民編著詩書文章、發表言論談吐是否合道。觀察他們的行為，凡是順應天意的，就稱為至善的行為；違背天意的，就稱為不善的行為。觀察他們的言辭談論，凡是順應天意的，就稱為至善的言談；違背天意的，就稱為不善的言談。觀察他們的刑罰政令，凡是順應天意的，就稱為至善的政刑；違背天意的，就稱為不善的政刑。因此確立天意作為最高法度，樹立天意作為根本準則，用來衡量天下王公大人卿大夫的仁與不仁，就好比辨別黑色與白色一樣黑白分明。所以墨子說：「當今天下的王公大人與士人君子，如果內心真想奉行正道、利益萬民，探求仁義的根本源頭，那麼上天的旨意是萬萬不可不順從的。順應上天的意願，正是天下行義的至高準則法度。」\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志中〉。墨子學派以兼愛天下為宗，開篇「是故子墨子之有天之，闢之無以異乎輪人之有規，匠人之有矩也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「是」、「有」、「天」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「是故子墨子之有天之闢之無以異乎輪人之有規匠人之有」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「今夫輪人操其規，將以量度天下之圜與不圜也，曰：中吾規者謂之圜，不中吾規者謂之不圜」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"mo-zi_ch-27_p-1_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"子墨子言曰：「今天下之君子之慾為仁義者，則不可不察義之所從出。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-1_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"既曰不可以不察義之所從出，然則義何從出？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-1_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"」子墨子曰：「義不從愚且賤者出，必自貴且知者出。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-1_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"何以知義之不從愚且賤者出，而必自貴且知者出也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-1_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"曰：義者，善政也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-1_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"何以知義之為善政也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-1_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"曰：天下有義則治，無義則亂，是以知義之為善政也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-1_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"夫愚且賤者，不得為政乎貴且知者，貴且知者然後得為政乎愚且賤者，此吾所以知義之不從愚且賤者出，而必自貴且知者出也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-1_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-1\",\n      \"order\": 9,\n      \"canonicalText\": \"然則孰為貴？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-1_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-1\",\n      \"order\": 10,\n      \"canonicalText\": \"孰為知？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-1_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-1\",\n      \"order\": 11,\n      \"canonicalText\": \"曰：天為貴，天為知而已矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-1_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-1\",\n      \"order\": 12,\n      \"canonicalText\": \"然則義果自天出矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-1_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-1\",\n      \"order\": 13,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"今天下之人曰：「當若天子之貴於諸侯，諸侯之貴於大夫，傐明知之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"然吾未知天之貴且知於天子也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"」子墨子曰：「吾所以知天之貴且知於天子者有矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"曰：天子為善，天能賞之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"天子為暴，天能罰之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"天子有疾病禍祟，必齋戒沐浴，潔為酒醴粢盛，以祭祀天鬼，則天能除去之，然吾未知天之祈福於天子也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"此吾所以知天之貴且知於天子者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 8,\n      \"canonicalText\": \"不止此而已矣，又以先王之書馴天明不解之道也知之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 9,\n      \"canonicalText\": \"曰：『明哲維天，臨君下土。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 10,\n      \"canonicalText\": \"』則此語天之貴且知於天子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 11,\n      \"canonicalText\": \"不知亦有貴知夫天者乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 12,\n      \"canonicalText\": \"曰：天為貴，天為知而已矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 13,\n      \"canonicalText\": \"然則義果自天出矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-2_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-2\",\n      \"order\": 14,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"是故子墨子曰：「今天下之君子，中實將欲遵道利民，本察仁義之本，天之意不可不慎也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"」既以天之意以為不可不慎已，然則天之將何欲何憎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"子墨子曰：「天之意不欲大國之攻小國也，大家之亂小家也，強之暴寡，詐之謀愚，貴之傲賤，此天之所不欲也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"不止此而已，欲人之有力相營，有道相教，有財相分也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"又欲上之強聽治也，下之強從事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"上強聽治，則國家治矣，下強從事則財用足矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"若國家治財用足，則內有以潔為酒醴粢盛，以祭祀天鬼；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"外有以為環璧珠玉，以聘撓四鄰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-3\",\n      \"order\": 9,\n      \"canonicalText\": \"諸侯之冤不興矣，邊境兵甲不作矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-3\",\n      \"order\": 10,\n      \"canonicalText\": \"內有以食飢息勞，持養其萬民，則君臣上下惠忠，父子弟兄慈孝。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-3\",\n      \"order\": 11,\n      \"canonicalText\": \"故唯毋明乎順天之意，奉而光施之天下，則刑政治，萬民和，國家富，財用足，百姓皆得煖衣飽食，便寧無憂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-3\",\n      \"order\": 12,\n      \"canonicalText\": \"」是故子墨子曰：「今天下之君子，中實將欲遵道利民，本察仁義之本，天之意不可不慎也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-3_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-3\",\n      \"order\": 13,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"且夫天子之有天下也，闢之無以異乎國君諸侯之有四境之內也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"今國君諸侯之有四境之內也，夫豈欲其臣國萬民之相為不利哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"今若處大國則攻小國，處大家則亂小家，欲以此求賞譽，終不可得，誅罰必至矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"夫天之有天下也，將無已異此。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"今若處大國則攻小國，處大都則伐小都，欲以此求福祿於天，福祿終不得，而禍祟必至矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"然有所不為天之所欲，而為天之所不欲，則夫天亦且不為人之所欲，而為人之所不欲矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"人之所不欲者何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"曰病疾禍祟也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"若已不為天之所欲，而為天之所不欲，是率天下之萬民以從事乎禍祟之中也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-4\",\n      \"order\": 10,\n      \"canonicalText\": \"故古者聖王明知天鬼之所福，而闢天鬼之所憎，以求興天下之利，而除天下之害。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-4\",\n      \"order\": 11,\n      \"canonicalText\": \"是以天之為寒熱也節，四時調，陰陽雨露也時，五穀孰，六畜遂，疾災戾疫凶饑則不至。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-4\",\n      \"order\": 12,\n      \"canonicalText\": \"」是故子墨子曰：「今天下之君子，中實將欲遵道利民，本察仁義之本，天意不可不慎也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-4_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-4\",\n      \"order\": 13,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-5_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"且夫天下蓋有不仁不祥者，曰當若子之不事父，弟之不事兄，臣之不事君也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-5_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"故天下之君子，與謂之不祥者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-5_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"今夫天兼天下而愛之，撽遂萬物以利之，若豪之末，非天之所為也，而民得而利之，則可謂否矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-5_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"然獨無報夫天，而不知其為不仁不祥也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-5_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"此吾所謂君子明細而不明大也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-6_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"且吾所以知天之愛民之厚者有矣，曰以磨為日月星辰，以昭道之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-6_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"制為四時春秋冬夏，以紀綱之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-6_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"雷降雪霜雨露，以長遂五穀麻絲，使民得而財利之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-6_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"列為山川谿谷，播賦百事，以臨司民之善否；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-6_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"為王公侯伯，使之賞賢而罰暴；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-6_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"賊金木鳥獸，從事乎五穀麻絲，以為民衣食之財。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-6_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"自古及今，未嘗不有此也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-6_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"今有人於此，驩若愛其子，竭力單務以利之，其子長，而無報子求父，故天下之君子與謂之不仁不祥。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-6_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"今夫天兼天下而愛之，撽遂萬物以利之，若豪之末，非天之所為，而民得而利之，則可謂否矣，然獨無報夫天，而不知其為不仁不祥也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-6_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"此吾所謂君子明細而不明大也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-7_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"且吾所以知天愛民之厚者，不止此而足矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-7_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"曰殺不辜者，天予不祥。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-7_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"不辜者誰也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-7_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"曰人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-7_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"予之不祥者誰也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-7_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"曰天也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-7_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"若天不愛民之厚，夫胡說人殺不辜，而天予之不祥哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-7_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"此吾之所以知天之愛民之厚也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"且吾所以知天之愛民之厚者，不止此而已矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"曰愛人利人，順天之意，得天之賞者有之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"憎人賊人，反天之意，得天之罰者亦有矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"夫愛人利人，順天之意，得天之賞者誰也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"曰若昔三代聖王，堯舜禹湯文武者是也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"堯舜禹湯文武焉所從事？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"曰從事兼，不從事別。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"兼者，處大國不攻小國，處大家不亂小家，強不劫弱，眾不暴寡，詐不謀愚，貴不傲賤。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"觀其事，上利乎天，中利乎鬼，下利乎人，三利無所不利，是謂天德。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 10,\n      \"canonicalText\": \"聚斂天下之美名而加之焉，曰：此仁也，義也，愛人利人，順天之意，得天之賞者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 11,\n      \"canonicalText\": \"不止此而已，書於竹帛，鏤之金石，琢之槃盂，傳遺後世子孫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 12,\n      \"canonicalText\": \"曰將何以為？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 13,\n      \"canonicalText\": \"將以識夫愛人利人，順天之意，得天之賞者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 14,\n      \"canonicalText\": \"皇矣道之曰：『帝謂文王，予懷明德，不大聲以色，不長夏以革，不識不知，順帝之則。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-15\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 15,\n      \"canonicalText\": \"』帝善其順法則也，故舉殷以賞之，使貴為天子，富有天下，名譽至今不息。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-16\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 16,\n      \"canonicalText\": \"故夫愛人利人，順天之意，得天之賞者，既可得留而已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-17\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 17,\n      \"canonicalText\": \"夫憎人賊人，反天之意，得天之罰者誰也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-18\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 18,\n      \"canonicalText\": \"曰若昔者三代暴王桀紂幽厲者是也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-19\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 19,\n      \"canonicalText\": \"桀紂幽厲焉所從事？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-20\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 20,\n      \"canonicalText\": \"曰從事別，不從事兼。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-21\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 21,\n      \"canonicalText\": \"別者，處大國則攻小國，處大家則亂小家，強劫弱，眾暴寡，詐謀愚，貴傲賤。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-22\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 22,\n      \"canonicalText\": \"觀其事，上不利乎天，中不利乎鬼，下不利乎人，三不利無所利，是謂天賊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-23\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 23,\n      \"canonicalText\": \"聚斂天下之醜名而加之焉，曰此非仁也，非義也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-24\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 24,\n      \"canonicalText\": \"憎人賊人，反天之意，得天之罰者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-25\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 25,\n      \"canonicalText\": \"不止此而已，又書其事於竹帛，鏤之金石，琢之槃盂，傳遺後世子孫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-26\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 26,\n      \"canonicalText\": \"曰將何以為？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-27\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 27,\n      \"canonicalText\": \"將以識夫憎人賊人，反天之意，得天之罰者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-28\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 28,\n      \"canonicalText\": \"大誓之道之曰：『紂越厥夷居，不肯事上帝，棄厥先神祇不祀，乃曰吾有命，毋廖𠏿務天下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-29\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 29,\n      \"canonicalText\": \"天亦縱棄紂而不葆。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-30\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 30,\n      \"canonicalText\": \"』察天以縱棄紂而不葆者，反天之意也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-31\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 31,\n      \"canonicalText\": \"故夫憎人賊人，反天之意，得天之罰者，既可得而知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-8_s-32\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-8\",\n      \"order\": 32,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"是故子墨子之有天之，闢之無以異乎輪人之有規，匠人之有矩也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"今夫輪人操其規，將以量度天下之圜與不圜也，曰：中吾規者謂之圜，不中吾規者謂之不圜。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"是以圜與不圜，皆可得而知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"此其故何？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"則圜法明也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 6,\n      \"canonicalText\": \"匠人亦操其矩，將以量度天下之方與不方也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 7,\n      \"canonicalText\": \"曰：中吾矩者謂之方，不中吾矩者謂之不方。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 8,\n      \"canonicalText\": \"是以方與不方，皆可得而知之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 9,\n      \"canonicalText\": \"此其故何？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 10,\n      \"canonicalText\": \"則方法明也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 11,\n      \"canonicalText\": \"故子墨子之有天之意也，上將以度天下之王公大人之為刑政也，下將以量天下之萬民為文學出言談也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 12,\n      \"canonicalText\": \"觀其行，順天之意，謂之善意行，反天之意，謂之不善意行；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 13,\n      \"canonicalText\": \"觀其言談，順天之意，謂之善言談，反天之意，謂之不善言談；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 14,\n      \"canonicalText\": \"觀其刑政，順天之意，謂之善刑政，反天之意，謂之不善刑政。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-15\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 15,\n      \"canonicalText\": \"故置此以為法，立此以為儀，將以量度天下之王公大人卿大夫之仁與不仁，譬之猶分黑白也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-16\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 16,\n      \"canonicalText\": \"是故子墨子曰：「今天下之王公大人士君子，中實將欲遵道利民，本察仁義之本，天之意不可不順也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-17\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 17,\n      \"canonicalText\": \"順天之意者，義之法也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-27_p-9_s-18\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-27\",\n      \"passageId\": \"mo-zi_ch-27_p-9\",\n      \"order\": 18,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
